ST.xhtml:p:
RTrigger1(CLK := g_biBoendeAvoidCheck);
RTrigger2(CLK := g_bLayerStartM1);

IF RTrigger1.Q THEN
  g_boBoendeCheckDone := FALSE;
  nCheckState := 10;
END_IF;

IF RTrigger2.Q THEN
  g_bBoendeAvoid := TRUE;
  g_boBoendeCheckDone := FALSE;
  g_bLayerStartM1 := FALSE;
END_IF;

dDDAxisPosInY := DDAxis.NCTOPLC.ACTPOS + dGantryRearChuckDis;

CASE nCheckState OF
  0:
    nCheckState := 0;
  10:
    dNextFasterPoint := g_fNextFasterPointM - g_diYWorkCoordinate + g_diYMachineCoordinate;
    dNextNearestPoint := g_fNextNearestPointM - g_diYWorkCoordinate + g_diYMachineCoordinate;
    IF (dNextNearestPoint > dGantryFrontChuckDis - dFrontChuckSafeDis AND dNextNearestPoint < dGantryFrontChuckDis + dFrontChuckSafeDis) OR
       (dNextFasterPoint > dGantryFrontChuckDis - dFrontChuckSafeDis AND dNextFasterPoint < dGantryFrontChuckDis + dFrontChuckSafeDis) OR
       (dNextNearestPoint > dDDAxisPosInY - dRearChuckSafeDis AND dNextNearestPoint < dDDAxisPosInY + dRearChuckSafeDis) OR
       (dNextFasterPoint > dDDAxisPosInY - dRearChuckSafeDis AND dNextFasterPoint < dDDAxisPosInY + dRearChuckSafeDis) THEN
      g_boBoendeCheckDone := FALSE;
      g_bBoendeCheckWarn := TRUE;
    ELSE
      IF (dNextFasterPoint < dDDAxisPosInY AND dNextNearestPoint < dDDAxisPosInY AND g_diYMachineCoordinate < dDDAxisPosInY) OR
         (dNextFasterPoint > dGantryFrontChuckDis AND dNextNearestPoint > dGantryFrontChuckDis AND g_diYMachineCoordinate > dGantryFrontChuckDis) OR
         ((dNextFasterPoint > dDDAxisPosInY AND dNextFasterPoint < dGantryFrontChuckDis) AND (dNextNearestPoint > dDDAxisPosInY AND dNextNearestPoint < dGantryFrontChuckDis) AND
         (g_diYMachineCoordinate > dDDAxisPosInY AND g_diYMachineCoordinate < dGantryFrontChuckDis)) THEN
        g_bBoendeAvoid := FALSE;
      ELSE
        g_bBoendeAvoid := TRUE;
      END_IF;
      g_boBoendeCheckDone := TRUE;
      nCheckState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  g_boBoendeCheckDone := FALSE;
  g_bBoendeCheckWarn := FALSE;
  nCheckState := 0;
END_IF;
